all></td><td class="wrap"><b><?=ce_h($r['local_language_name'])?>:</b> <?=ce_h($r['local_theme'])?></td><td><?=ce_h($r['audience'])?><?php if($r['department_names']!==''):?><br><small><?=ce_h($r['department_names'])?></small><?php endif;?></td><td><span class="church-badge"><?=((int)$r['is_active']===1?'Active':'Inactive')?></span></td><td><div class="church-table-actions"><button type="button" class="btn btn-info btn-sm js-action" data-action="view" data-record='<?=ce_h(json_encode($r,JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_TAG))?>'><i class="fas fa-eye"></i></button><button type="button" class="btn btn-primary btn-sm js-action" data-action="edit" data-record='<?=ce_h(json_encode($r,JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_TAG))?>'><i class="fas fa-edit"></i></button><button type="button" class="btn btn-danger btn-sm js-action" data-action="delete" data-id="<?=(int)$r['id']?>" data-name="<?=ce_h($r['english_theme'])?>"><i class="fas fa-trash"></i></button></div></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="church-empty">No annual themes found.</td></tr><?php endif;?></tbody></table></div></div>
