ments):?><div class="church-empty">No departments found.</div><?php endif;?></div></div><label class="church-check"><input type="checkbox" name="is_active" id="is_active" value="1" checked> Active theme</label></div></div><div class="church-modal-footer"><button type="button" class="btn btn-outline js-close">Cancel</button><button type="submit" class="btn btn-primary"><i class="fas fa-save"></i> Save Theme</button></div></form></div></div>
