<script>
const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));
function openModal(id){$('#backdrop').classList.add('show');$(id).classList.add('show');document.body.classList.add('cms-modal-open')}
function closeModal(){$$('.church-modal,.church-modal-backdrop').forEach(x=>x.classList.remove('show'));document.body.classList.remove('cms-modal-open')}
$$('.js-close').forEach(x=>x.addEventListener('click',closeModal));$('#backdrop').addEventListener('click',closeModal);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
function toggleDepartments(){$('#deptBox').classList.toggle('show',$('#audience').value==='Selected Departments')}
$('#audience').addEventListener('change',toggleDepartments);$('#selectAll').addEventListener('click',()=>$$('#deptBox input[type=checkbox]').forEach(x=>x.checked=true));$('#clearAll').addEventListener('click',()=>$$('#deptBox input[type=checkbox]').forEach(x=>x.checked=false));

$('#addBtn').addEventListener('click',()=>{$('#recordForm').reset();$('#recordId').value='';$('#formTitle').textContent='Add Theme';$$('#deptBox input[type=checkbox]').forEach(x=>x.checked=false);document.getElementById('theme_year').value=new Date().getFullYear();document.getElementById('local_language_name').value='';document.getElementById('is_active').checked=true;toggleDepartments();openModal('#formModal')});
$$('.js-action').forEach(btn=>btn.addEventListener('click',()=>{if(btn.dataset.action==='delete'){$('#deleteId').value=btn.dataset.id||'';$('#deleteName').textContent=btn.dataset.name||'this record';openModal('#deleteModal');return}const r=JSON.parse(btn.dataset.record||'{}');if(btn.dataset.action==='view'){const fields={'Year':r.theme_year,'English Theme':r.english_theme,'Local Language':r.local_language_name,'Local Theme':r.local_theme,'Scripture':r.scripture_reference,'Explanation':r.explanation,'Audience':r.audience+(r.department_names?' — '+r.department_names:''),'Status':Number(r.is_active)===1?'Active':'Inactive'};$('#details').innerHTML=Object.entries(fields).map(([k,v])=>`<div class="modal-detail ${k==='Explanation'||k==='Notes'?'full':''}"><b>${k}</b><span>${String(v??'').trim()||'-'}</span></div>`).join('');openModal('#viewModal');return}$('#recordForm').reset();$('#recordId').value=r.id||'';$('#formTitle').textContent='Edit Theme';['theme_year','english_theme','local_theme','scripture_reference','explanation','audience'].forEach(k=>document.getElementById(k).value=r[k]??'');const languageSelect=document.getElementById('local_language_name'),savedLanguage=String(r.local_language_name??'');if(savedLanguage&&!Array.from(languageSelect.options).some(o=>o.value===savedLanguage)){languageSelect.add(new Option(savedLanguage,savedLanguage))}languageSelect.value=savedLanguage;document.getElementById('is_active').checked=Number(r.is_active)===1;const ids=String(r.department_ids||'').split(',');$$('#deptBox input[type=checkbox]').forEach(x=>x.checked=ids.includes(x.value));toggleDepartments();openModal('#formModal')}));
$('#recordSearch').addEventListener('input',e=>{const q=e.target.value.toLowerCase().trim();$$('.church-table tbody tr[data-search]').forEach(row=>row.hidden=q!==''&&!row.dataset.search.includes(q))});
$('#refreshRecords').addEventListener('click',()=>{const s=$('#recordSearch');s.value='';s.dispatchEvent(new Event('input'))});
</script></div></div><?php require_once '../includes/footer.php';?>